// ublByID indexes UBLCatalog.
var ublByID = sync.OnceValue(func() map[string]*rules.RuleInfo {
	m := make(map[string]*rules.RuleInfo, len(UBLCatalog))
	for i := range UBLCatalog {
		m[UBLCatalog[i].ID] = &UBLCatalog[i]
	}
	return m
})
